import{_ as o,o as t,c,a5 as n}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"Plan — Subtask theo vai trò & Trình soạn chia phần","description":"","frontmatter":{},"headers":[],"relativePath":"feature/subtask-role-workspaces/plan.md","filePath":"feature/subtask-role-workspaces/plan.md"}'),i={name:"feature/subtask-role-workspaces/plan.md"};function a(d,e,s,r,h,l){return t(),c("div",null,[...e[0]||(e[0]=[n('<h1 id="plan-—-subtask-theo-vai-tro-trinh-soan-chia-phan" tabindex="-1">Plan — Subtask theo vai trò &amp; Trình soạn chia phần <a class="header-anchor" href="#plan-—-subtask-theo-vai-tro-trinh-soan-chia-phan" aria-label="Permalink to &quot;Plan — Subtask theo vai trò &amp; Trình soạn chia phần&quot;">​</a></h1><p>&gt; Bước ② theo <code>docs/rule/feature-workflow.md</code>. Dựa trên <code>spec.md</code> (đã chốt 2026-11-10). &gt; Mục <strong>0</strong>: user đã duyệt cả 4 phương án đề xuất ngày 2026-11-10 (0.1 A, 0.2 poi-ooxml, 0.3 một route, 0.4 batch <code>kind=NEWSLETTER</code>).</p><h2 id="_0-phuong-an-đa-duyet" tabindex="-1">0. Phương án đã duyệt <a class="header-anchor" href="#_0-phuong-an-đa-duyet" aria-label="Permalink to &quot;0. Phương án đã duyệt&quot;">​</a></h2><h3 id="_0-1-luu-phan-section-o-đau-—-đe-xuat-a" tabindex="-1">0.1 Lưu phần (section) ở đâu — <strong>đề xuất A</strong> <a class="header-anchor" href="#_0-1-luu-phan-section-o-đau-—-đe-xuat-a" aria-label="Permalink to &quot;0.1 Lưu phần (section) ở đâu — **đề xuất A**&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>A. Collection riêng <code>task_sections</code> (đề xuất)</th><th>B. Nhúng vào <code>TaskDocument.typeMetadata.sections</code></th></tr></thead><tbody><tr><td>Revision theo phần (§5.4)</td><td>Mỗi phần một document, <code>revision</code> riêng, CAS bằng <code>findAndModify</code> theo <code>{taskId, sectionKey, revision}</code></td><td>Phải CAS cả TaskDocument → hai người sửa hai phần khác nhau chặn nhau, trái §5.4</td></tr><tr><td>Phiên bản (§16.12)</td><td>Collection <code>task_section_versions</code> riêng, không phình task</td><td>Nhúng phiên bản làm task phình, chạm giới hạn 16MB với EVENT/KOL dài</td></tr><tr><td>Lọc phần I cho Client (AC10)</td><td>Query lọc <code>visibility</code> ở DB</td><td>Lọc trong code sau khi đọc hết</td></tr><tr><td>Tác động code cũ</td><td>Không đụng schema <code>tasks</code> (chỉ thêm <code>subtaskRole</code>)</td><td>Mọi chỗ ghi TaskDocument phải giữ nguyên map</td></tr></tbody></table><p>POST và SURVEY: <strong>nội dung vẫn nằm ở <code>PostDocument</code> / survey hiện có</strong> (publisher và luồng publish đọc từ đó). Document <code>task_sections</code> của các phần này chỉ giữ trạng thái, revision, ghi chú, con trỏ; snapshot phiên bản vẫn chụp nội dung thật. Các loại khác (EVENT, PRESS, KOL, WORKSHOP, EMAIL, VIDEO.SCRIPT) giữ nội dung trong <code>task_sections.content</code>.</p><h3 id="_0-2-xuat-docx-—-đe-xuat-them-org-apache-poi-poi-ooxml-vao-business-service" tabindex="-1">0.2 Xuất DOCX — <strong>đề xuất thêm <code>org.apache.poi:poi-ooxml</code> vào business-service</strong> <a class="header-anchor" href="#_0-2-xuat-docx-—-đe-xuat-them-org-apache-poi-poi-ooxml-vao-business-service" aria-label="Permalink to &quot;0.2 Xuất DOCX — **đề xuất thêm `org.apache.poi:poi-ooxml` vào business-service**&quot;">​</a></h3><p>PDF dùng lại <code>openpdf</code> + mẫu <code>PackageExportRenderer</code> / <code>PackageProposalLayout</code> có sẵn (đã có font tiếng Việt <code>openpdf-fonts-extra</code>). DOCX chưa có thư viện nào trong repo. Phương án khác là sinh DOCX ở web bằng npm <code>docx</code>, nhưng như vậy phần lọc O/I và &quot;chỉ phần đã duyệt cho Client&quot; phải tin frontend; nên làm ở backend. <strong>Dependency mới cần user đồng ý.</strong></p><h3 id="_0-3-route-trinh-soan-—-đe-xuat-mot-route-chia-theo-loai" tabindex="-1">0.3 Route trình soạn — <strong>đề xuất một route, chia theo loại</strong> <a class="header-anchor" href="#_0-3-route-trinh-soan-—-đe-xuat-mot-route-chia-theo-loai" aria-label="Permalink to &quot;0.3 Route trình soạn — **đề xuất một route, chia theo loại**&quot;">​</a></h3><p>Giữ <code>/workspaces/:id/tasks/:taskId/editor</code>. POST &amp; SHORT_VIDEO dùng <code>pages/editor</code> hiện có (thêm khối). SURVEY và 5 loại mới render qua <code>pages/task-editor/</code> (mới) với <code>SectionFrame</code> dùng chung; trang chọn editor theo <code>task.type</code>. Không tạo route riêng cho từng loại.</p><h3 id="_0-4-gui-newsletter-—-đe-xuat-đi-qua-đuong-batch-co-san-gan-kind-newsletter" tabindex="-1">0.4 Gửi Newsletter — <strong>đề xuất đi qua đường batch có sẵn, gắn <code>kind = NEWSLETTER</code></strong> <a class="header-anchor" href="#_0-4-gui-newsletter-—-đe-xuat-đi-qua-đuong-batch-co-san-gan-kind-newsletter" aria-label="Permalink to &quot;0.4 Gửi Newsletter — **đề xuất đi qua đường batch có sẵn, gắn `kind = NEWSLETTER`**&quot;">​</a></h3><p>Dùng lại <code>MailSendService</code> → <code>MailDeliveryStore</code> (<code>mail_batches</code>, <code>mail_deliveries</code>) → <code>MailDeliveryService.deliverNext</code>. Thêm cột <code>kind</code> vào <code>mail_batches</code>; <code>MailDeliveryService</code> khi gặp batch <code>NEWSLETTER</code> bỏ qua <code>MailQuotaService</code> (giới hạn ngày mail hệ thống) và dùng bộ đếm Newsletter riêng (§16.1). Không viết hàng đợi thứ hai.</p><hr><h2 id="_1-thanh-phan-backend-brandhub-business-service" tabindex="-1">1. Thành phần backend (<code>brandhub-business-service</code>) <a class="header-anchor" href="#_1-thanh-phan-backend-brandhub-business-service" aria-label="Permalink to &quot;1. Thành phần backend (`brandhub-business-service`)&quot;">​</a></h2><h3 id="_1-1-danh-muc-co-đinh-trong-code" tabindex="-1">1.1 Danh mục cố định trong code <a class="header-anchor" href="#_1-1-danh-muc-co-đinh-trong-code" aria-label="Permalink to &quot;1.1 Danh mục cố định trong code&quot;">​</a></h3><ul><li><code>model/enums/TaskType.java</code>: thêm <code>SHORT_VIDEO, KOL_BOOKING, WORKSHOP, EMAIL_NEWSLETTER</code>.</li><li><code>model/enums/PackageServiceType.java</code>: thêm <code>SHORT_VIDEO, KOL_BOOKING, EMAIL_NEWSLETTER</code>. Ánh xạ service type → task type nằm ở <code>CampaignPlanValidator.TASK_TYPES</code> (thêm 3 mục, đổi <code>WORKSHOP_SUPPORT</code> từ <code>SURVEY</code> sang <code>WORKSHOP</code>); <code>PackageOfferingValidator.validateStandardUnits</code> là switch không <code>default</code>, phải thêm đơn vị cho 3 loại mới.</li><li><strong>Mới</strong> <code>service/impl/task/TaskCatalog.java</code>: map tĩnh <code>TaskType → List&lt;RoleDef(role, List&lt;SectionDef(key, visibility O|I)&gt;)&gt;</code> đúng bảng spec §3. Một class, không interface, không cấu hình.</li><li><strong>Mới</strong> <code>controller/TaskCatalogController.java</code>: <code>GET /api/v1/task-catalog/{taskType}</code>.</li></ul><h3 id="_1-2-subtask" tabindex="-1">1.2 Subtask <a class="header-anchor" href="#_1-2-subtask" aria-label="Permalink to &quot;1.2 Subtask&quot;">​</a></h3><ul><li><code>document/TaskDocument.java</code> record <code>Subtask</code>: thêm <code>String subtaskRole</code> (cuối record). Thêm constructor tương thích cũ để mọi chỗ gọi hiện tại không đổi.</li><li><code>CampaignSubtaskService</code> / <code>CampaignSubtaskController</code>: <code>Details</code>/<code>Row</code> thêm <code>subtaskRole</code>; validate thuộc <code>TaskCatalog</code> của task cha (AC3); <code>PATCH /status</code> từ chối <code>FINISHED</code> khi <code>subtaskRole != null</code>.</li><li><code>CampaignTaskStore.draftTask</code>: sau khi tạo task cha, sinh subtask theo <code>TaskCatalog</code> (assignee null, <code>dueDate</code> = hạn task cha, status TODO) (§16.9).</li><li>Tự FINISHED (§5.3): <code>SectionService</code> sau mỗi chuyển trạng thái gọi <code>CampaignSubtaskService.syncRoleSubtasks(taskId)</code> — subtask có vai trò chuyển FINISHED khi mọi phần nó sở hữu ở trạng thái cuối, và quay về IN_PROGRESS nếu phần bị trả/mở lại.</li></ul><h3 id="_1-3-phan" tabindex="-1">1.3 Phần <a class="header-anchor" href="#_1-3-phan" aria-label="Permalink to &quot;1.3 Phần&quot;">​</a></h3><ul><li><strong>Mới</strong> <code>document/TaskSectionDocument.java</code> (<code>task_sections</code>): <code>id, workspaceId, taskId, sectionKey, visibility, status, revision, content (Map), returnNote, returnedBy, lastEditorRole (POST.CAPTION: CONTENT|EDITING), clientPendingSince, clientReminderSentAt, updatedAt</code>. Unique index <code>{taskId, sectionKey}</code>.</li><li><strong>Mới</strong> <code>document/TaskSectionVersionDocument.java</code> (<code>task_section_versions</code>): <code>taskId, sectionKey, versionNo, content snapshot, submittedBy, submittedAt</code> + nhật ký sự kiện <code>task_section_events</code> (<code>action, actorId, note, at</code>). Hai collection, không xoá (§16.12).</li><li><strong>Mới</strong> <code>service/impl/task/SectionPolicy.java</code>: tính <code>canView/canEdit/canSubmit/canApprove/canReturn/canReopen/canRestore</code> theo §4, §5.2, §16.10, §16.13. Dùng lại <code>TaskApprovalPolicy.Context/Snapshot</code> và <code>CampaignSubtaskService.supervisor</code>. Luật chồng phần POST/VIDEO.CAPTION nằm ở đây.</li><li><strong>Mới</strong> <code>service/impl/task/SectionService.java</code>: list (lọc theo người xem — Client chỉ O &amp; <code>INTERNAL_APPROVED+</code>), patch (CAS revision; sửa phần đã duyệt → <code>SUBMITTED</code>), submit (ghi version), approve, return (note bắt buộc), reopen, restore, versions/compare. Phát thông báo (§1.6), huỷ lịch khi Client trả (§1.7).</li><li><strong>Mới</strong> <code>controller/TaskSectionController.java</code>: các endpoint §9.2 + <code>GET /sections/{key}/versions</code>, <code>GET /sections/{key}/versions/{no}</code>, <code>POST /sections/{key}/restore/{no}</code>.</li><li>Task cũ / phần chưa có document: <code>SectionService</code> coi như <code>DRAFT</code>, chủ = điều phối, tạo document lười ở lần ghi đầu (spec §11). <strong>Không backfill.</strong></li></ul><h3 id="_1-4-ap-quyen-vao-endpoint-cu" tabindex="-1">1.4 Áp quyền vào endpoint cũ <a class="header-anchor" href="#_1-4-ap-quyen-vao-endpoint-cu" aria-label="Permalink to &quot;1.4 Áp quyền vào endpoint cũ&quot;">​</a></h3><ul><li><code>TaskPostController</code> / service lưu bài: so sánh <code>SavePostRequest</code> với <code>PostDocument</code> hiện tại, xác định trường thay đổi → phần (<code>caption/hashtags</code>→CAPTION, media→MEDIA, platforms/scheduledAt→CHANNELS); trường thuộc phần không có quyền mà thay đổi → <code>FORBIDDEN</code> (AC8). Bump revision phần tương ứng. Response thêm <code>sections</code>.</li><li><code>SurveyController</code> <code>POST /survey</code>: kiểm <code>SURVEY.FORM</code>.</li><li>Thay chỗ gọi <code>TaskApprovalPolicy.assignee</code> cho ghi nội dung bằng <code>SectionPolicy</code> khi task có subtask theo vai trò; task không có → giữ nguyên (không regression).</li><li><code>TaskApprovalService</code> submit: thêm <code>TASK_SECTIONS_UNAPPROVED</code>. Với task có subtask vai trò: bỏ bước <code>reviewStep = CLIENT</code>; khi mọi phần O đạt <code>CLIENT_APPROVED</code> (hoặc <code>INTERNAL_APPROVED</code> nếu không cần Client) → gọi luồng chuyển task cha sang đã duyệt hiện có (§16.5).</li><li><code>exception/ErrorCode.java</code>: thêm <code>SECTION_INVALID_TRANSITION, TASK_SECTIONS_UNAPPROVED, NEWSLETTER_NOT_APPROVED, MAIL_MONTHLY_QUOTA_EXCEEDED</code>.</li></ul><h3 id="_1-5-newsletter" tabindex="-1">1.5 Newsletter <a class="header-anchor" href="#_1-5-newsletter" aria-label="Permalink to &quot;1.5 Newsletter&quot;">​</a></h3><ul><li><code>document/MailRecipientGroupDocument.Entry</code>: thêm <code>consent, consentSource, importedAt</code>.</li><li><code>MailRecipientController</code>: <code>POST /mail-recipient-groups/import</code> (multipart) — parse bằng <code>commons-csv</code> (đã có), dedupe email, loại không consent / suppressed / sai định dạng, trả 4 con số (AC13).</li><li><strong>Mới</strong> <code>service/NewsletterService.java</code>: kiểm AC14 (phần CONTENT + DESIGN đạt trạng thái cuối, quyền người gọi), kiểm quota tháng, render từ blocks phần CONTENT/DESIGN bằng renderer mail-templates hiện có, gọi <code>MailSendService</code> tạo batch <code>kind=NEWSLETTER</code>, sender name = <code>ClientProfile.displayName</code>, domain BrandHub (AC17). <code>send-test</code> dùng lại <code>MailSendService.sendTest</code>.</li><li><strong>Mới</strong> <code>service/NewsletterQuotaService.java</code>: đếm theo <code>agency_id</code> + tháng (giờ <code>Asia/Ho_Chi_Minh</code> như <code>MailQuotaService.ZONE</code>); limit lấy từ gói của agency (<code>SubscriptionPlanName</code> → 1.000/10.000/50.000, cấu hình <code>newsletter.quota.basic|pro|enterprise</code>); giới hạn tốc độ <code>newsletter.rate.per-day</code>. Hết giữa batch → <code>DEFERRED</code> như cơ chế hiện có.</li><li><code>MailDeliveryService</code>: nhánh <code>NEWSLETTER</code> dùng <code>NewsletterQuotaService</code> thay <code>MailQuotaService</code>.</li><li>Suppression theo Client (§16.6): <code>mail_suppressions</code> thêm <code>client_profile_id</code>; unsubscribe từ mail Newsletter ghi kèm client của workspace (<code>WorkspaceMember.clientProfileId</code> của Client trong workspace). <code>MailSuppressionStore</code> thêm <code>isSuppressedForClient</code>. Mail hệ thống giữ logic cũ.</li><li><code>MailSendController GET /mail-quota</code>: thêm <code>monthlyUsed, monthlyLimit, planName</code>.</li><li>Phần <code>EMAIL.REPORT</code>: số liệu đọc trực tiếp từ batch (<code>MailBatchService.detail</code>), chỉ lưu ô nhận xét.</li></ul><h3 id="_1-6-thong-bao-§16-7" tabindex="-1">1.6 Thông báo (§16.7) <a class="header-anchor" href="#_1-6-thong-bao-§16-7" aria-label="Permalink to &quot;1.6 Thông báo (§16.7)&quot;">​</a></h3><ul><li><code>UserNotificationService</code>: thêm <code>sectionEvent(recipient, workspaceId, taskId, sectionKey, action)</code> (in-app, <code>actionUrl</code> = trình soạn).</li><li>Email: Client khi có phần chờ duyệt; chủ phần khi bị trả — qua <code>MailSendService.sendSystem</code> với template hệ thống mới.</li><li><strong>Mới</strong> <code>@Scheduled</code> <code>SectionReminderJob</code> (mỗi giờ): phần <code>INTERNAL_APPROVED</code> có <code>clientPendingSince &lt; now-48h</code> và <code>clientReminderSentAt</code> null hoặc cũ hơn 48h → gửi nhắc. Không tự duyệt.</li></ul><h3 id="_1-7-huy-lich-khi-client-tra-§11" tabindex="-1">1.7 Huỷ lịch khi Client trả (§11) <a class="header-anchor" href="#_1-7-huy-lich-khi-client-tra-§11" aria-label="Permalink to &quot;1.7 Huỷ lịch khi Client trả (§11)&quot;">​</a></h3><ul><li>Đã kiểm 2026-11-10: chưa có hàm huỷ lịch. <code>PostSchedulePublishJob</code> (business-service) chỉ đăng post khi task cha <code>FINISHED</code> + <code>lastSubmission.outcome = APPROVED</code>.</li><li>POST/VIDEO: đưa task cha về <code>IN_PROGRESS</code> + thêm <code>PostService.cancelTaskSchedule</code> (post <code>SCHEDULED/APPROVED</code> → <code>DRAFT</code>, xoá <code>scheduledAt</code>). Không đụng publisher-service.</li><li>EMAIL: <code>MailBatchService.cancelSystem(batchId)</code> với batch đang chờ; <code>batchId</code> lưu trong content phần <code>EMAIL.AUDIENCE</code>.</li></ul><h3 id="_1-8-xuat-file-§16-11" tabindex="-1">1.8 Xuất file (§16.11) <a class="header-anchor" href="#_1-8-xuat-file-§16-11" aria-label="Permalink to &quot;1.8 Xuất file (§16.11)&quot;">​</a></h3><ul><li><strong>Mới</strong> <code>service/impl/task/SectionExportService.java</code> + endpoint <code>GET /tasks/{taskId}/export</code> (<code>?format</code> suy ra theo loại: PRESS → DOCX, khác → PDF).</li><li>PDF: theo mẫu <code>PackageExportRenderer</code> (openpdf). DOCX: poi-ooxml (0.2). Chỉ phần O; logo <code>ClientProfile.logoUrl</code>; agency xuất mọi trạng thái, phần chưa <code>CLIENT_APPROVED</code> đóng dấu &quot;Bản nháp&quot;; Client chỉ phần <code>CLIENT_APPROVED</code>.</li></ul><h2 id="_2-db-thay-đoi-brandhub-infrastructure-docs-database-migrations" tabindex="-1">2. DB thay đổi (<code>brandhub-infrastructure/docs/database/migrations/</code>) <a class="header-anchor" href="#_2-db-thay-đoi-brandhub-infrastructure-docs-database-migrations" aria-label="Permalink to &quot;2. DB thay đổi (`brandhub-infrastructure/docs/database/migrations/`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Nội dung</th></tr></thead><tbody><tr><td><code>2026-11-1x-subtask-role-sections.js</code> (mongosh)</td><td>tạo <code>task_sections</code>, <code>task_section_versions</code>, <code>task_section_events</code> + index (<code>{taskId,sectionKey}</code> unique, <code>{workspaceId,status}</code>, <code>{status,clientPendingSince}</code>); cập nhật validator <code>tasks</code> nếu đang ràng buộc enum <code>type</code> / field subtask; thêm <code>subtaskRole</code> optional.</td></tr><tr><td><code>2026-11-1x-newsletter.sql</code> (Postgres, additive như mẫu 11-06)</td><td><code>mail_batches.kind VARCHAR(16) NOT NULL DEFAULT &#39;TEMPLATE&#39;</code>; <code>mail_suppressions.client_profile_id UUID</code> + index; bảng <code>newsletter_monthly_usage(agency_id, month, used, PK(agency_id,month))</code>.</td></tr></tbody></table><p>Không seed, không backfill dữ liệu cũ. <code>TaskSampleSeeder</code> thêm một task POST có subtask vai trò để demo. User tự chạy migration (như 11-06).</p><h2 id="_3-web-brandhub-web" tabindex="-1">3. Web (<code>brandhub-web</code>) <a class="header-anchor" href="#_3-web-brandhub-web" aria-label="Permalink to &quot;3. Web (`brandhub-web`)&quot;">​</a></h2><ul><li>Type: <code>src/types/task.ts</code>, <code>src/pages/campaign/types.ts</code> — 4 TaskType mới, <code>subtaskRole</code>, type <code>TaskSection</code>.</li><li><strong>Mới</strong> <code>src/services/taskSectionService.ts</code>, <code>src/hooks/useTaskSections.ts</code> (React Query; mutation gửi <code>expectedRevision</code>, xử lý <code>TASK_REVISION_CONFLICT</code> → banner tải lại).</li><li><strong>Mới</strong> <code>src/components/task-sections/</code>: <code>SectionFrame</code> (tiêu đề, chủ phần, badge trạng thái, nút theo <code>can*</code>, banner returned/locked/conflict), <code>SectionStatusBadge</code>, <code>SectionReturnDialog</code>, <code>SectionVersionDrawer</code> (list + so sánh + khôi phục).</li><li>POST/VIDEO: <code>src/pages/editor/index.tsx</code> + <code>TaskEditorControls</code>, <code>MediaDropzone</code>, <code>DocsCaptionEditor</code>, <code>ScheduleModal</code> — bọc từng vùng bằng <code>SectionFrame</code>, disable theo quyền; thêm khối Brief (POST) / Kịch bản (VIDEO); slot rỗng <code>VIDEO.SHOOT</code>, <code>VIDEO.EDIT</code> (component placeholder có props <code>section</code>, để Ân gắn code).</li><li><strong>Mới</strong> <code>src/pages/task-editor/</code>: <code>index.tsx</code> (chọn editor theo type), <code>SurveyEditor</code> (bọc <code>SurveyOverviewCard</code> + khối Phân phối, Báo cáo), <code>EventEditor</code>, <code>PressEditor</code>, <code>KolEditor</code>, <code>WorkshopEditor</code> (Registration dùng lại form builder survey), <code>NewsletterEditor</code> (dùng lại <code>BlockBuilder</code>, <code>MailPreview</code>, <code>RecipientPicker</code> từ <code>pages/mail-templates</code>). Một component <code>SectionListField</code> dùng chung cho các trường dạng bảng (agenda, vendor, media list…).</li><li>Subtask: <code>TimelineSubtaskCreator.tsx</code>, <code>tasks/components/CampaignSubtasks.tsx</code>, <code>WorkItemSubtasksList.tsx</code> — bước &quot;Gợi ý theo danh mục&quot;, badge vai trò, ẩn FINISHED thủ công với subtask có vai trò.</li><li><code>tasks/components/TaskWorkflowContent.tsx</code>: nút mở trình soạn cho mọi loại + tóm tắt &quot;x/y phần đã duyệt&quot;.</li><li>Timeline (§16.15): <code>CampaignTimelineGrid.tsx</code> hiện trạng thái phần của subtask + cờ trễ hạn / chờ Client.</li><li>Client portal: <code>pages/portal/components/ApprovalQueueList.tsx</code> thêm danh sách phần chờ duyệt (Duyệt / Trả lại bắt buộc ghi chú).</li><li>Mail: <code>pages/mail-templates</code> — dialog import CSV, hiển thị quota tháng.</li><li>Export: nút xuất ở trình soạn và portal.</li><li><strong>i18n</strong>: <code>src/i18n/locales/{vi,en}/tasks.json</code>, <code>editor.json</code>, <code>campaign.json</code>, <code>mailTemplate.json</code>, <code>client.json</code> (key theo spec AC19, key-parallel).</li><li><strong>Theme</strong>: chỉ dùng token/<code>dark:</code> có sẵn (AC20); không thêm màu mới.</li></ul><h2 id="_4-mobile-brandhub-mobile-app" tabindex="-1">4. Mobile (<code>brandhub-mobile-app</code>) <a class="header-anchor" href="#_4-mobile-brandhub-mobile-app" aria-label="Permalink to &quot;4. Mobile (`brandhub-mobile-app`)&quot;">​</a></h2><ul><li><code>src/screens/content/TaskDetailScreen.tsx</code>: tab &quot;Phần&quot; — danh sách phần chỉ đọc + Duyệt/Trả theo <code>can*</code> từ API. Service gọi <code>/sections</code>.</li><li><code>src/types</code>: 4 TaskType mới (tránh crash enum label — <code>src/i18n/enumLabel.ts</code>).</li><li>Locale: <code>src/i18n/locales/vi/*</code>, <code>en.json</code>.</li></ul><h2 id="_5-luong-du-lieu-chinh" tabindex="-1">5. Luồng dữ liệu chính <a class="header-anchor" href="#_5-luong-du-lieu-chinh" aria-label="Permalink to &quot;5. Luồng dữ liệu chính&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Deploy campaign → CampaignTaskStore.draftTask → task cha + subtask theo TaskCatalog (chưa gán)</span></span>\n<span class="line"><span>Chủ phần PATCH /sections/{key} (expectedRevision) → SectionPolicy → CAS task_sections</span></span>\n<span class="line"><span>  POST/SURVEY: ghi PostDocument/survey + bump revision phần</span></span>\n<span class="line"><span>submit → version snapshot + event → notify supervisor/Manager</span></span>\n<span class="line"><span>approve (nội bộ) → INTERNAL_APPROVED → phần O: clientPendingSince, notify + email Client</span></span>\n<span class="line"><span>Client approve → CLIENT_APPROVED → syncRoleSubtasks → (đủ phần O) task cha APPROVED</span></span>\n<span class="line"><span>Client return → RETURNED + note → huỷ lịch publish/mail → notify chủ phần</span></span>\n<span class="line"><span>EMAIL_SEND send → NewsletterService (AC14, quota) → mail_batches(kind=NEWSLETTER) → MailDeliveryService</span></span></code></pre></div><h2 id="_6-thu-tu-build" tabindex="-1">6. Thứ tự build <a class="header-anchor" href="#_6-thu-tu-build" aria-label="Permalink to &quot;6. Thứ tự build&quot;">​</a></h2><ol><li>BE nền: TaskType/PackageServiceType, <code>TaskCatalog</code>, <code>subtaskRole</code>, catalog endpoint, migration Mongo.</li><li>BE phần: <code>TaskSectionDocument</code> + versions/events, <code>SectionPolicy</code>, <code>SectionService</code>, controller, ErrorCode. Unit test policy + chuyển trạng thái.</li><li>BE gắn luồng cũ: lưu bài/survey theo phần, submit gating, Client per-section thay <code>reviewStep=CLIENT</code>, auto FINISHED, sinh subtask khi deploy.</li><li>BE thông báo + reminder job + huỷ lịch.</li><li>BE Newsletter: migration SQL, import CSV, quota tháng, kind NEWSLETTER, suppression Client, send/test.</li><li>BE export PDF/DOCX.</li><li>Web nền: types, service/hook, <code>SectionFrame</code>; POST editor chia phần → test E2E luồng POST đầy đủ.</li><li>Web các editor còn lại + subtask creator + timeline + portal + mail import/quota + export.</li><li>Mobile tab Phần.</li><li>i18n/theme rà soát, chạy test.md. Sau khi chạy thật: cập nhật FR/SRS (ngoài scope code).</li></ol><p>Bàn giao trong một đợt như user chốt; thứ tự trên chỉ là thứ tự làm.</p><h2 id="_7-rui-ro" tabindex="-1">7. Rủi ro <a class="header-anchor" href="#_7-rui-ro" aria-label="Permalink to &quot;7. Rủi ro&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Rủi ro</th><th>Giảm thiểu</th></tr></thead><tbody><tr><td>Thêm TaskType làm vỡ <code>switch</code>/map ở web, mobile, ai-service, publisher</td><td>Grep toàn bộ repo trước bước 1; fallback label cho type lạ</td></tr><tr><td>Endpoint lưu bài cũ áp quyền theo phần gây regression task cũ</td><td>Chỉ bật khi task có subtask vai trò; test case 15 trong spec</td></tr><tr><td>Validator Mongo <code>tasks</code> từ chối field/enum mới</td><td>Migration bước 1 cập nhật validator trước khi deploy code</td></tr><tr><td>Newsletter làm tắc hàng đợi mail hệ thống</td><td>Quota/tốc độ riêng; <code>deliverNext</code> ưu tiên batch hệ thống</td></tr><tr><td>Code video của Ân chưa push</td><td>Chỉ chừa slot + key quyền; không định nghĩa UI; Ân gắn sau</td></tr><tr><td>Dependency mới poi-ooxml tăng kích thước jar</td><td>Chấp nhận nếu user duyệt 0.2; nếu không, PRESS cũng xuất PDF</td></tr><tr><td>Phạm vi lớn, một đợt</td><td>Mỗi bước 1–9 kết thúc bằng test pass trước khi sang bước sau</td></tr></tbody></table>',44)])])}const g=o(i,[["render",a]]);export{p as __pageData,g as default};
